#!/usr/bin/env python3
"""NOVA 15 MAX visual layer."""
CSS=r'''<style>
:root{--xbg:#05070b;--xline:rgba(255,255,255,.08);--xblue:#7c8fff;--xcyan:#48dec4}
html,body{background:var(--xbg)!important;color:#f5f8fc!important;scroll-behavior:smooth}
body:before{background:radial-gradient(900px 500px at 4% -8%,rgba(87,111,255,.19),transparent 62%),radial-gradient(850px 560px at 105% 105%,rgba(42,210,181,.10),transparent 60%),linear-gradient(180deg,rgba(5,7,11,.94),rgba(5,7,11,.985)),url('/background.svg?v=NOVA15')!important}
body:after{opacity:.34!important;background-size:48px 48px!important}
.sidebar{width:286px!important;padding:16px 12px 20px!important;background:rgba(5,9,15,.92)!important;border-right:1px solid var(--xline)!important;box-shadow:24px 0 80px rgba(0,0,0,.36)!important;backdrop-filter:blur(26px)!important;scrollbar-gutter:stable}
.logo{width:48px!important;height:48px!important;border-radius:16px!important;background:linear-gradient(145deg,#8294ff,#46d9c1)!important;box-shadow:0 14px 42px rgba(84,111,255,.30)!important}.brand b{font-size:21px!important}.brand small{font-size:8px!important;letter-spacing:.22em!important}
.nav{gap:3px!important}.section{margin:20px 10px 7px!important;color:#4f5e74!important;font-size:8px!important;letter-spacing:.19em!important}.nav a{min-height:43px!important;padding:10px 12px!important;border-radius:13px!important;color:#96a4b8!important;font-size:12px!important}.nav a i{width:22px!important;font-size:16px!important}.nav a:hover{background:rgba(255,255,255,.055)!important;color:#fff!important;transform:translateX(3px)!important}.nav a.active{background:linear-gradient(100deg,rgba(124,143,255,.20),rgba(72,222,196,.055))!important;border-color:rgba(124,143,255,.25)!important;box-shadow:inset 3px 0 var(--xblue),0 8px 26px rgba(0,0,0,.15)!important;color:#fff!important}
.server{display:none!important}
.main{width:calc(100% - 286px)!important;margin-left:286px!important;padding:0 42px 70px!important}.topbar{height:74px!important;margin:0 -42px 32px!important;padding:0 42px!important;background:rgba(5,8,13,.74)!important;border-bottom:1px solid var(--xline)!important;backdrop-filter:blur(24px)!important}.topbar .title{font-size:12px!important;font-weight:800!important}.wrap{max-width:1680px!important}
.hero{margin:7px 0 27px!important}.eyebrow{font-size:9px!important;letter-spacing:.25em!important;color:#8497ff!important}.hero h1{font-size:46px!important;letter-spacing:-.068em!important;margin:8px 0 9px!important}.hero p{font-size:13px!important;color:#7f8da1!important}
.card{background:linear-gradient(145deg,rgba(17,24,36,.91),rgba(8,12,19,.95))!important;border:1px solid var(--xline)!important;border-radius:18px!important;box-shadow:0 26px 80px rgba(0,0,0,.30)!important;backdrop-filter:blur(14px)!important}.grid4{gap:14px!important}.metric{min-height:145px!important;padding:21px!important}.metric .label{font-size:9px!important;letter-spacing:.12em!important}.metric .value{font-size:35px!important;margin-top:13px!important}.metric .sub{font-size:10px!important}
.dashboard-grid{gap:15px!important;margin-top:15px!important}.actions{gap:10px!important}.action{min-height:112px!important;padding:16px!important;border-radius:14px!important;background:rgba(255,255,255,.022)!important;border-color:rgba(255,255,255,.065)!important}.action:hover{transform:translateY(-3px)!important;background:rgba(124,143,255,.055)!important;border-color:rgba(124,143,255,.30)!important;box-shadow:0 16px 35px rgba(0,0,0,.18)!important}
.btn,button{min-height:40px!important;padding:10px 14px!important;border-radius:11px!important;background:linear-gradient(135deg,#7c8fff,#536ee8)!important;box-shadow:0 10px 28px rgba(76,96,220,.22)!important}.btn.secondary{background:rgba(255,255,255,.045)!important;border-color:var(--xline)!important}.btn.danger{background:#34151f!important;border-color:#693142!important}
input,select,.input{min-height:43px!important;background:rgba(5,9,15,.88)!important;border-color:rgba(255,255,255,.10)!important;border-radius:11px!important}input:focus,select:focus{border-color:#778cff!important;box-shadow:0 0 0 3px rgba(119,140,255,.12)!important}label{font-size:10px!important;color:#a9b5c5!important}
.table-wrap{border:1px solid rgba(255,255,255,.055)!important;border-radius:14px!important;background:rgba(4,8,13,.28)!important}table{min-width:720px!important}th{padding:14px 11px!important;font-size:8px!important;letter-spacing:.13em!important}td{padding:14px 11px!important;border-bottom-color:rgba(255,255,255,.055)!important}.badge{padding:6px 9px!important;border-radius:999px!important}.notice{padding:13px!important;border-radius:13px!important}.kv{border-radius:13px!important}.code{border-radius:13px!important}.footer{font-size:9px!important}
.login-shell{background:radial-gradient(700px 500px at 50% 38%,rgba(86,111,255,.15),transparent 67%)!important}.login-card{width:min(470px,100%)!important;padding:36px!important;border-radius:24px!important;background:rgba(9,14,22,.90)!important;border-color:rgba(255,255,255,.10)!important;box-shadow:0 45px 130px rgba(0,0,0,.62)!important}
@media(max-width:1100px){.sidebar{width:252px!important}.main{width:calc(100% - 252px)!important;margin-left:252px!important;padding-left:26px!important;padding-right:26px!important}.topbar{margin-left:-26px!important;margin-right:-26px!important;padding-left:26px!important;padding-right:26px!important}}
@media(max-width:760px){.sidebar{width:280px!important}.main{width:100%!important;margin-left:0!important;padding:0 15px 42px!important}.topbar{margin:0 -15px 20px!important;padding:0 15px!important;height:64px!important}.hero h1{font-size:33px!important}.grid4{grid-template-columns:1fr 1fr!important}.dashboard-grid,.split{grid-template-columns:1fr!important}.formgrid,.actions{grid-template-columns:1fr!important}.nova-float{right:14px!important;bottom:14px!important}.nova-float span{display:none!important}}
@media(max-width:470px){.grid4{grid-template-columns:1fr!important}.hero h1{font-size:29px!important}.card{border-radius:15px!important;padding:15px!important}}
</style>'''
def apply(nova):
    nova.NOVA_CSS += CSS
    return nova
